DO $$
DECLARE r record;
  keep text[] := ARRAY['activate_beta_tester','activate_stays_beta_tester','add_marketing_topup_credits','admin_update_noir_driver_status','approve_corporate_subscription','approve_verification_with_certificate','award_coalition_points','award_qr_scan','calculate_business_impact_scorecard','calculate_user_impact_metrics','check_and_award_badges','check_api_rate_limit','check_auth_rate_limit_v2','check_business_access_rate_limit','check_function_exists','check_rate_limit','check_rate_limit_secure','claim_business_lead','claim_directory_business','claim_email_unsubscribe','claim_enterprise_leader_seats','claim_kayla_events','consume_marketing_credit','create_sales_agent_application_secure','create_user_referral','credit_partner_referral_on_payment','credit_wallet','debit_wallet','enqueue_email','exec_sql','generate_claim_token','generate_referral_code','generate_white_label_api_key','get_active_campaigns','get_active_referral_codes','get_admin_notification_preferences','get_admin_verification_queue','get_agent_badges_with_progress','get_agent_leaderboard','get_agent_qr_analytics','get_agent_tier_progress','get_application_details_secure','get_applications_for_review_secure','get_b2b_impact_metrics','get_business_locations','get_business_referral_info','get_businesses_by_city_and_categories','get_campaign_leaderboard','get_claim_campaign_candidates','get_coalition_stats','get_community_impact_summary','get_community_wealth_metrics','get_developer_monthly_usage','get_directory_business_by_id','get_directory_business_by_slug','get_directory_businesses','get_directory_categories','get_download_trends','get_founding_slots_claimed_count','get_holiday_campaign_recipients','get_holiday_campaign_stats','get_impact_leaderboard','get_job_apply_email','get_leads_needing_enrichment','get_lease_listing','get_material_analytics','get_materials_with_filters','get_nearby_businesses','get_parent_business_analytics','get_platform_commission_summary','get_platform_stats','get_public_external_leads','get_public_profile_info','get_security_metrics','get_similar_lease_listings','get_social_share_counts','get_sponsor_pipeline_summary','get_test_questions_for_user','get_user_hbcu_status','get_user_milestone_progress','get_user_role','handle_api_error','has_role','increment_community_wealth','increment_download_count','increment_event_attendees','increment_sponsor_click','increment_sponsor_impression','increment_topic_views','insert_fraud_alerts_batch','is_admin_secure','join_challenge','list_landing_categories','list_landing_cities','list_partner_directories','log_activity','log_api_usage','log_failed_auth_attempt','log_user_activity','mark_qr_scan_converted','match_embeddings','process_business_referral','process_pending_referrals','record_business_metric','record_challenge_activity','record_commission','redeem_beta_code','refill_expired_marketing_credits','refund_marketing_credit','reject_corporate_subscription','reset_auth_rate_limit','review_queue_counts','review_queue_leads','search_lease_listings','search_public_businesses','secure_change_user_role','security_autopilot_snapshot','set_cashier_pin','submit_business','supplier_search_api','track_material_download','track_qr_scan','update_sentiment_trends','update_user_streak','validate_api_key','validate_input','validate_password_complexity','validate_referral_code','validate_test_answers','verify_business_claim_token','verify_cashier_pin','verify_claim_token'];
  lock text[] := ARRAY['exec_sql','credit_wallet','debit_wallet','secure_change_user_role','add_marketing_topup_credits','admin_update_noir_driver_status','approve_corporate_subscription','approve_verification_with_certificate','reject_corporate_subscription','record_commission','refill_expired_marketing_credits','refund_marketing_credit','consume_marketing_credit','insert_fraud_alerts_batch','reset_auth_rate_limit','get_admin_notification_preferences','get_admin_verification_queue','get_security_metrics','security_autopilot_snapshot','get_platform_commission_summary','get_applications_for_review_secure','get_application_details_secure','get_holiday_campaign_recipients','get_claim_campaign_candidates','generate_white_label_api_key','process_pending_referrals','credit_partner_referral_on_payment','claim_kayla_events','get_leads_needing_enrichment','review_queue_counts','review_queue_leads','get_sponsor_pipeline_summary','increment_community_wealth','award_coalition_points','calculate_business_impact_scorecard','calculate_user_impact_metrics','update_sentiment_trends'];
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS fn, p.proname
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname='public' AND p.prosecdef AND p.prorettype <> 'trigger'::regtype
      AND has_function_privilege('anon', p.oid, 'execute')
      AND (p.proname = ANY(lock) OR NOT (p.proname = ANY(keep)))
      AND NOT EXISTS (SELECT 1 FROM pg_policies pl WHERE coalesce(pl.qual,'')||coalesce(pl.with_check,'') ILIKE '%'||p.proname||'(%')
      AND p.proname NOT LIKE 'get_directory_%' AND p.proname NOT LIKE 'get_businesses_by_%'
      AND p.proname NOT LIKE 'get_public_%' AND p.proname NOT LIKE '%unsubscribe%'
      AND p.proname NOT LIKE '%invitation_by_token%' AND p.proname NOT LIKE 'verify_%claim%'
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon', r.fn);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated, service_role', r.fn);
  END LOOP;
END $$;